import {brandDesign} from './brand-designs.js?v=23.0.0';
import {makeInteriorPlan} from './interior-blueprints.js?v=38.0.0';
const clothing=new Set(['shirt','hoodie','cardigan','jacket','pants','shorts']);
export function departmentOf(p){return ['food','drink'].includes(p.type)?'Food & drinks':clothing.has(p.type)?'Clothing':['shoes','sandals'].includes(p.type)?'Footwear':['perfume','skincare','makeup','lipstick','mascara'].includes(p.type)?'Beauty':['headphones','earbuds','tracker','mouse','keyboard','stylus','charger','cable','speaker'].includes(p.type)?'Tech':['ring','bracelet','necklace','watch','earrings','digitalwatch'].includes(p.type)?'Jewelry & watches':['buildingtoy','cardgame','toy','plush'].includes(p.type)?'Creative play':['bag','wallet','crossbody','backpack','duffel','hat','belt','scarf','sunglasses'].includes(p.type)?'Bags & accessories':'Home & stationery';}
export function shopProfile(store,products){const list=store.products||products.filter(p=>p.store===store.id),counts={};list.forEach(p=>counts[departmentOf(p)]=(counts[departmentOf(p)]||0)+1);const dominant=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'Clothing';const kind=store.businessKind==='food'?'cafe':!list.length?'service':['ross','marshalls','target','nordstrom'].includes(store.id)?'department':dominant==='Beauty'?'beauty':dominant==='Tech'?'tech':dominant==='Creative play'?'toys':dominant==='Jewelry & watches'?'jewelry':dominant==='Bags & accessories'?'boutique':dominant==='Home & stationery'?'home':'apparel';const design=brandDesign(store,store.businessKind||kind);return {...design,kind,departments:Object.entries(counts).map(([name,count])=>({name,count})),luxury:store.tier>=5,floor:design.floor,fixture:design.fixture,accent:design.accent,title:design.title||{department:'The discovery floor',apparel:'The fitting studio',boutique:'The leather-goods salon',beauty:'The beauty counter',tech:'The hands-on gallery',toys:'The building room',jewelry:'The jewelry salon',home:'The everyday studio',cafe:'The menu counter',service:'The service lounge'}[kind]};}
export function displaySelection(products,store,department='all',page=0,size=6){const all=products.filter(p=>p.store===store&&(department==='all'||departmentOf(p)===department));const pages=Math.max(1,Math.ceil(all.length/size)),index=Math.max(0,Math.min(pages-1,page));return {items:all.slice(index*size,index*size+size),count:all.length,page:index,pages,start:all.length?index*size+1:0,end:Math.min((index+1)*size,all.length)};}
export function displayPoint(fixture){return {x:fixture.x+fixture.width/2,y:fixture.y+fixture.height+20};}
export const interiorPlan=makeInteriorPlan;
